16	package org.springframework.samples.petclinic.service;
17	
18	import org.springframework.dao.DataAccessException;
19	import org.springframework.dao.EmptyResultDataAccessException;
20	import org.springframework.data.domain.Page;
21	import org.springframework.data.domain.Pageable;
22	import org.springframework.orm.ObjectRetrievalFailureException;
23	import org.springframework.samples.petclinic.model.*;
24	import org.springframework.samples.petclinic.repository.*;
25	import org.springframework.samples.petclinic.util.CustomerCodeGenerator;
26	import org.springframework.samples.petclinic.util.TextNormalizer;
27	import org.springframework.stereotype.Service;
28	import org.springframework.transaction.annotation.Transactional;
29	
30	import java.time.LocalDate;
31	import java.util.Collection;
32	import java.util.List;
33	import java.util.Set;
34	import java.util.function.Supplier;
35	
36	/**
37	 * Mostly used as a facade for all Petclinic controllers
38	 * Also a placeholder for @Transactional and @Cacheable annotations
39	 *
40	 * @author Michael Isvy
41	 * @author Vitaliy Fedoriv
42	 */
43	@Service
44	public class ClinicServiceImpl implements ClinicService {
45	
46	    private final PetRepository petRepository;
47	    private final VetRepository vetRepository;
48	    private final OwnerRepository ownerRepository;
49	    private final VisitRepository visitRepository;
50	    private final SpecialtyRepository specialtyRepository;
51	    private final PetTypeRepository petTypeRepository;
52	
53	    public ClinicServiceImpl(
54	        PetRepository petRepository,
55	        VetRepository vetRepository,
56	        OwnerRepository ownerRepository,
57	        VisitRepository visitRepository,
58	        SpecialtyRepository specialtyRepository,
59	        PetTypeRepository petTypeRepository) {
60	        this.petRepository = petRepository;
61	        this.vetRepository = vetRepository;
62	        this.ownerRepository = ownerRepository;
63	        this.visitRepository = visitRepository;
64	        this.specialtyRepository = specialtyRepository;
65	        this.petTypeRepository = petTypeRepository;
66	    }
67	
68	    @Override
69	    @Transactional(readOnly = true)
70	    public Collection<Pet> findAllPets() throws DataAccessException {
71	        return petRepository.findAll();
72	    }
73	
74	    @Override
75	    @Transactional(readOnly = true)
76	    public Page<Pet> findPets(Pageable pageable) throws DataAccessException {
77	        return petRepository.findAll(pageable);
78	    }
79	
80	    @Override
81	    @Transactional
82	    public void deletePet(Pet pet) throws DataAccessException {
83	        petRepository.delete(pet);
84	    }
85	
86	    @Override
87	    @Transactional(readOnly = true)
88	    public Visit findVisitById(int visitId) throws DataAccessException {
89	        return findEntityById(() -> visitRepository.findById(visitId));
90	    }
91	
92	    @Override
93	    @Transactional(readOnly = true)
94	    public Collection<Visit> findAllVisits() throws DataAccessException {
95	        return visitRepository.findAll();
96	    }
97	
98	    @Override
99	    @Transactional
100	    public void deleteVisit(Visit visit) throws DataAccessException {
101	        visitRepository.delete(visit);
102	    }
103	
104	    @Override
105	    @Transactional(readOnly = true)
106	    public Vet findVetById(int id) throws DataAccessException {
107	        return findEntityById(() -> vetRepository.findById(id));
108	    }
109	
110	    @Override
111	    @Transactional(readOnly = true)
112	    public Collection<Vet> findAllVets() throws DataAccessException {
113	        return vetRepository.findAll();
114	    }
115	
116	    @Override
117	    @Transactional
118	    public void saveVet(Vet vet) throws DataAccessException {
119	        vetRepository.save(vet);
120	    }
121	
122	    @Override
123	    @Transactional
124	    public void deleteVet(Vet vet) throws DataAccessException {
125	        vetRepository.delete(vet);
126	    }
127	
128	    @Override
129	    @Transactional(readOnly = true)
130	    public Collection<Owner> findAllOwners() throws DataAccessException {
131	        return ownerRepository.findAll();
132	    }
133	
134	    @Override
135	    @Transactional(readOnly = true)
136	    public Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException {
137	        if (lastName != null) {
138	            return ownerRepository.findByLastName(lastName, pageable);
139	        }
140	        return ownerRepository.findAll(pageable);
141	    }
142	
143	    @Override
144	    @Transactional
145	    public void deleteOwner(Owner owner) throws DataAccessException {
146	        ownerRepository.delete(owner);
147	    }
148	
149	    @Override
150	    @Transactional(readOnly = true)
151	    public PetType findPetTypeById(int petTypeId) {
152	        return findEntityById(() -> petTypeRepository.findById(petTypeId));
153	    }
154	
155	    @Override
156	    @Transactional(readOnly = true)
157	    public Collection<PetType> findAllPetTypes() throws DataAccessException {
158	        return petTypeRepository.findAll();
159	    }
160	
161	    @Override
162	    @Transactional
163	    public void savePetType(PetType petType) throws DataAccessException {
164	        petTypeRepository.save(petType);
165	    }
166	
167	    @Override
168	    @Transactional
169	    public void deletePetType(PetType petType) throws DataAccessException {
170	        petTypeRepository.delete(petType);
171	    }
172	
173	    @Override
174	    @Transactional(readOnly = true)
175	    public Specialty findSpecialtyById(int specialtyId) {
176	        return findEntityById(() -> specialtyRepository.findById(specialtyId));
177	    }
178	
179	    @Override
180	    @Transactional(readOnly = true)
181	    public Collection<Specialty> findAllSpecialties() throws DataAccessException {
182	        return specialtyRepository.findAll();
183	    }
184	
185	    @Override
186	    @Transactional
187	    public void saveSpecialty(Specialty specialty) throws DataAccessException {
188	        specialtyRepository.save(specialty);
189	    }
190	
191	    @Override
192	    @Transactional
193	    public void deleteSpecialty(Specialty specialty) throws DataAccessException {
194	        specialtyRepository.delete(specialty);
195	    }
196	
197	    @Override
198	    @Transactional(readOnly = true)
199	    public Collection<PetType> findPetTypes() throws DataAccessException {
200	        return petRepository.findPetTypes();
201	    }
202	
203	    @Override
204	    @Transactional(readOnly = true)
205	    public Owner findOwnerById(int id) throws DataAccessException {
206	        return findEntityById(() -> ownerRepository.findById(id));
207	    }
208	
209	    @Override
210	    @Transactional(readOnly = true)
211	    public Pet findPetById(int id) throws DataAccessException {
212	        return findEntityById(() -> petRepository.findById(id));
213	    }
214	
215	    @Override
216	    @Transactional
217	    public void savePet(Pet pet) throws DataAccessException {
218	        pet.setType(findPetTypeById(pet.getType().getId()));
219	        petRepository.save(pet);
220	    }
221	
222	    @Override
223	    @Transactional
224	    public void saveVisit(Visit visit) throws DataAccessException {
225	        visitRepository.save(visit);
226	
227	    }
228	
229	    @Override
230	    @Transactional(readOnly = true)
231	    public Collection<Vet> findVets() throws DataAccessException {
232	        return vetRepository.findAll();
233	    }
234	
235	    @Override
236	    @Transactional
237	    public void createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
238	        if (ownerRepository.existsByTelephone(owner.getTelephone())) {
239	            throw new DuplicateTelephoneException(owner.getTelephone());
240	        }
241	        if (!sharesHousehold && sharesHouseholdWithExistingOwner(owner)) {
242	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
243	        }
244	        if (owner.getRegistrationDate() == null) {
245	            owner.setRegistrationDate(LocalDate.now());
246	        }
247	        owner.setCustomerCode(
248	            CustomerCodeGenerator.format(owner.getLastName(), ownerRepository.count() + 1));
249	        ownerRepository.save(owner);
250	    }
251	
252	    @Override
253	    @Transactional
254	    public void saveOwner(Owner owner) throws DataAccessException {
255	        ownerRepository.save(owner);
256	    }
257	
258	    /**
259	     * Report whether another owner already shares this owner's household, i.e. has the same last name and
260	     * address compared case-insensitively and with runs of whitespace collapsed.
261	     */
262	    private boolean sharesHouseholdWithExistingOwner(Owner owner) {
263	        String address = TextNormalizer.normalize(owner.getAddress());
264	        if (address == null) {
265	            return false;
266	        }
267	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
268	            .anyMatch(existing -> address.equals(TextNormalizer.normalize(existing.getAddress())));
269	    }
270	
271	    @Override
272	    @Transactional(readOnly = true)
273	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
274	        return ownerRepository.findByLastName(lastName);
275	    }
276	
277	    @Override
278	    @Transactional(readOnly = true)
279	    public Collection<Visit> findVisitsByPetId(int petId) {
280	        return visitRepository.findByPetId(petId);
281	    }
282	
283	    @Override
284	    @Transactional(readOnly = true)
285	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
286	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
287	    }
288	
289	    private <T> T findEntityById(Supplier<T> supplier) {
290	        try {
291	            return supplier.get();
292	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
293	            // Just ignore not found exceptions for Jdbc/Jpa realization
294	            return null;
295	        }
296	    }
297	
298	}
